<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import AppButton from '@/components/ui/AppButton.vue'
import { uploadProductAsset } from '@/lib/api'
import type { Product } from '@/types'
const props=defineProps<{ merchantId:string; product?:Product|null; disabled?:boolean }>(); const emit=defineEmits<{save:[payload:any];cancel:[]}>()
const uploadingPrimary=ref(false),uploadingReferences=ref(false),uploadError=ref('')
const inferCategory=(category:string,name:string)=>{const c=category.toLowerCase(),n=name.toLowerCase();if(c.includes('shoe'))return'shoes';if(c.includes('blazer')||c.includes('jacket'))return'outerwear';if(c.includes('top')||c.includes('shirt'))return'top';if(c.includes('bottom')||c.includes('trouser')||c.includes('skirt'))return'bottom';if(c.includes('dress'))return'dress';if(n.includes('bag')||n.includes('tote'))return'bag';if(n.includes('earring')||n.includes('hoop'))return'earrings';if(n.includes('necklace'))return'necklace';return'other_accessory'}

const form=reactive({name:props.product?.name||'',description:props.product?.description||'',price:props.product?.price||0,currency:props.product?.currency||'NGN',category:props.product?.category||'Tops',try_on_category:props.product?.try_on_category||'',style_audience:props.product?.style_audience||'unisex',primary_image_url:props.product?.primary_image_url||'',reference_images:(props.product?.reference_images||[]).map(x=>x.url).join('\n'),product_url:props.product?.product_url||'',sizes:(props.product?.sizes||[]).join(', '),colours:(props.product?.colours||[]).join(', '),tags:(props.product?.tags||[]).join(', '),stock_status:props.product?.stock_status||'in_stock'})
const preparedType=computed(()=>form.try_on_category||inferCategory(form.category,form.name))
const preparedSummary=computed(()=>`${form.name || 'Untitled product'}. ${form.description || 'Add a description so Mirror can preserve the important visual details.'}`)
function submit(){const refs=form.reference_images.split('\n').map(x=>x.trim()).filter(Boolean);emit('save',{...form,price:Number(form.price),try_on_category:form.try_on_category||inferCategory(form.category,form.name),reference_images:refs.map((url,i)=>({url,view:i===0?'front':'detail'})),visual_description:`${form.name}. ${form.description}`,generation_constraints:{preserveColour:true,preservePattern:true,preserveLogo:true},sizes:form.sizes.split(',').map(x=>x.trim()).filter(Boolean),colours:form.colours.split(',').map(x=>x.trim()).filter(Boolean),tags:form.tags.split(',').map(x=>x.trim()).filter(Boolean)})}
async function uploadPrimary(file?:File){if(!file)return;uploadingPrimary.value=true;uploadError.value='';try{form.primary_image_url=await uploadProductAsset(file,props.merchantId)}catch(e){uploadError.value=e instanceof Error?e.message:'Image upload failed.'}finally{uploadingPrimary.value=false}}
async function uploadReferences(files?:FileList|null){if(!files?.length)return;uploadingReferences.value=true;uploadError.value='';try{const urls=await Promise.all([...files].slice(0,4).map(file=>uploadProductAsset(file,props.merchantId)));form.reference_images=[form.reference_images,...urls].filter(Boolean).join('\n')}catch(e){uploadError.value=e instanceof Error?e.message:'Reference upload failed.'}finally{uploadingReferences.value=false}}
</script>
<template><form class="grid gap-4" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label class="text-xs font-medium">Name<input v-model="form.name" required class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Category<select v-model="form.category" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option>Blazers</option><option>Tops</option><option>Bottoms</option><option>Dresses</option><option>Shoes</option><option>Accessories</option></select></label><label class="text-xs font-medium">Shopper collection<select v-model="form.style_audience" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option value="womenswear">Womenswear</option><option value="menswear">Menswear</option><option value="unisex">Unisex</option></select><span class="mt-1 block font-normal text-muted">Controls which stylist conversations may recommend this item.</span></label><label class="text-xs font-medium">Try-on type<select v-model="form.try_on_category" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option value="">Auto detect</option><option value="top">Top</option><option value="outerwear">Outerwear</option><option value="dress">Dress</option><option value="bottom">Bottom</option><option value="shoes">Shoes</option><option value="bag">Bag</option><option value="earrings">Earrings</option><option value="necklace">Necklace</option><option value="headwear">Headwear</option><option value="other_accessory">Other accessory</option></select></label><label class="text-xs font-medium">Price<input v-model.number="form.price" required min="0" type="number" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Currency<input v-model="form.currency" required class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label></div><label class="text-xs font-medium">Description<textarea v-model="form.description" rows="3" class="mt-2 w-full rounded-xl border border-line p-3"></textarea></label><div class="grid gap-3 rounded-xl border border-line p-4"><label class="text-xs font-medium">Primary product image URL<input v-model="form.primary_image_url" required type="url" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="w-fit cursor-pointer rounded-full bg-ink px-4 py-2.5 text-xs font-semibold text-white"><input type="file" accept="image/*" class="hidden" @change="uploadPrimary(($event.target as HTMLInputElement).files?.[0])"/>{{uploadingPrimary?'Uploading…':'Upload primary image'}}</label><img v-if="form.primary_image_url" :src="form.primary_image_url" alt="Product image preview" class="h-28 w-24 rounded-xl object-cover"/></div><div class="grid gap-3 rounded-xl border border-line p-4"><label class="text-xs font-medium">Extra reference image URLs <span class="font-normal text-muted">(one per line)</span><textarea v-model="form.reference_images" rows="3" class="mt-2 w-full rounded-xl border border-line p-3" placeholder="https://.../side.jpg\nhttps://.../detail.jpg"></textarea></label><label class="w-fit cursor-pointer rounded-full border border-ink px-4 py-2.5 text-xs font-semibold"><input type="file" accept="image/*" multiple class="hidden" @change="uploadReferences(($event.target as HTMLInputElement).files)"/>{{uploadingReferences?'Uploading…':'Upload reference images'}}</label></div><p v-if="uploadError" role="alert" class="text-xs text-red-700">{{uploadError}}</p><label class="text-xs font-medium">Retailer checkout URL<input v-model="form.product_url" required type="url" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><div class="grid gap-4 sm:grid-cols-3"><label class="text-xs font-medium">Sizes<input v-model="form.sizes" placeholder="S, M, L" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Colours<input v-model="form.colours" placeholder="Navy, Black" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Tags<input v-model="form.tags" placeholder="workwear, modest" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label></div><label class="text-xs font-medium">Stock<select v-model="form.stock_status" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option value="in_stock">In stock</option><option value="low_stock">Low stock</option><option value="out_of_stock">Out of stock</option></select></label><div class="rounded-[1.1rem] border border-line bg-paper p-4"><div class="flex items-center justify-between"><div><p class="text-[10px] font-semibold uppercase tracking-[.18em] text-muted">Mirror preparation</p><p class="mt-1 text-xs font-semibold">{{ preparedType }} · {{form.style_audience}}</p></div><span class="rounded-full bg-white px-2.5 py-1 text-[10px] font-semibold">Auto-prepared</span></div><p class="mt-3 text-xs leading-5 text-muted">{{ preparedSummary }}</p><p class="mt-2 text-[10px] leading-4 text-muted">Colour, pattern, logo and distinctive product details are marked for preservation. Side/detail reference images are especially useful for shoes, bags and jewellery.</p></div><div class="flex justify-end gap-2"><AppButton variant="ghost" :disabled="disabled" @click="$emit('cancel')">Cancel</AppButton><AppButton type="submit" :disabled="disabled||uploadingPrimary||uploadingReferences">{{disabled?'Saving…':'Save product'}}</AppButton></div></form></template>
